//! CXA-B281.a — the golden above-the-fold inventory freeze.
//!
//! The committed snapshot under `crates/presentation/__inventories__/` is
//! generated by `freeze_inventory` (application) through the real
//! presentation adapter; this suite proves that regenerating it from the LIVE
//! manifest is byte-stable, and pins the domain serializer's determinism at
//! the freeze boundary.

use std::path::Path;

use coxagent_application::use_cases::{freeze_inventory, FrozenInventory};
use coxagent_domain::PanelInventoryEntry;
use coxagent_presentation::fold_freeze_adapter::ManifestFreezeSource;

/// Where the golden file lives (repo-root relative).
fn golden_path() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../presentation/__inventories__/above_the_fold_panels.golden")
}

fn read_golden() -> String {
    let p = golden_path();
    std::fs::read_to_string(&p).unwrap_or_else(|e| {
        panic!(
            "missing {} — run `cargo run -p coxagent-app --bin freeze_fold_inventory`: {e}",
            p.display()
        )
    })
}

/// Regenerate via the REAL port implementation (no IO inside the use case):
/// identical inputs to `cargo run --bin freeze_fold_inventory`.
fn regenerate_data_lines() -> Vec<String> {
    #[allow(clippy::expect_used)] // test fixture: a failure here IS the signal
    let inv = freeze_inventory(&ManifestFreezeSource).expect("live manifest freezes");
    inv.render("").lines().map(str::to_owned).collect()
}

#[test]
fn ac1_every_committed_data_line_round_trips_through_the_domain_type() {
    for line in read_golden().lines().filter(|l| l.starts_with('{')) {
        let e = PanelInventoryEntry::parse_canonical(line)
            .unwrap_or_else(|err| panic!("unparsable committed record `{line}`: {err}"));
        assert_eq!(
            e.to_canonical_json(),
            line,
            "record must re-serialize identically"
        );
    }
}

#[test]
fn ac3_regeneration_from_the_live_view_tree_is_byte_stable_against_the_commit() {
    let golden = read_golden();
    let golden_data: Vec<&str> = golden.lines().filter(|l| l.starts_with('{')).collect();
    let fresh = regenerate_data_lines();
    let fresh_refs: Vec<&str> = fresh.iter().map(String::as_str).collect();
    assert_eq!(
        golden_data, fresh_refs,
        "committed snapshot drifted from the live manifest — regenerate"
    );
    // Order attribution: records ascend by order_index without gaps.
    for (i, line) in golden_data.iter().enumerate() {
        #[allow(clippy::expect_used)]
        let e = PanelInventoryEntry::parse_canonical(line).expect("parses");
        #[allow(clippy::expect_used)] // 7-row file; truncation impossible
        let want = u32::try_from(i).expect("row count fits u32");
        assert_eq!(e.order_index, want, "order_index must be dense");
    }
}

#[test]
fn ac4_deterministic_hash_keys_are_stable_across_calls() {
    // The hash feeding each row is a pure function; two consecutive freezes
    // of the same declaration must agree entry-for-entry.
    #[allow(clippy::expect_used)] // pure functions over real types
    let a: FrozenInventory = freeze_inventory(&ManifestFreezeSource).expect("freezes");
    #[allow(clippy::expect_used)]
    let b: FrozenInventory = freeze_inventory(&ManifestFreezeSource).expect("freezes");
    assert_eq!(a.entries, b.entries);
    assert!(!a.entries.is_empty());
}
